        r'entanglement', r'superposition', r'coherence', r'rydberg'
    ],
    'black_hole': [
        r'black hole', r'event horizon', r'hawking', r'schwarzschild', r'kerr',
        r'singularity', r'accretion', r'gravitational', r'bh ', r'gravitational wave'
    ],
    'DNA': [
        r' DNA ', r'genome', r'genomic', r'genetics', r'nucleotide', r'double helix',
        r'base pair', r'sequencing', r'chromosome', r'gene', r'RNA'
    ],
    'music_history': [
        r'music', r'composer', r'symphony', r'baroque', r'classical', r'romantic',
        r'renaissance', r'medieval', r'opera', r'jazz', r'rock', r'folk'
    ],
}

patterns = {k:[re.compile(p, re.I) for p in v] for k,v in subjects.items()}


def extract_text_pdf(path, max_pages=2, max_chars=50000):
    text_parts = []
    try:
        with pdfplumber.open(path) as pdf:
            for i, page in enumerate(pdf.pages[:max_pages]):
                t = page.extract_text() or ''
                if t:
                    text_parts.append(t)
                if sum(len(x) for x in text_parts) > max_chars:
                    break
    except Exception:
        return ''
    return '\n'.join(text_parts)


def extract_text_docx(path, max_chars=50000):
    # docx is a zip; main text in word/document.xml
    try:
        with zipfile.ZipFile(path) as z:
            with z.open('word/document.xml') as f:
                xml = f.read().decode('utf-8', 'ignore')
        # strip tags
        text = re.sub(r'<[^>]+>', ' ', xml)
        return text[:max_chars]
    except Exception:
        return ''


def extract_text_pptx(path, max_chars=50000):
    # pptx is a zip; slides in ppt/slides/slide*.xml
    texts = []
    try:
        with zipfile.ZipFile(path) as z:
            slide_files = sorted([n for n in z.namelist() if n.startswith('ppt/slides/slide') and n.endswith('.xml')])
            for sf in slide_files:
                with z.open(sf) as f:
                    xml = f.read().decode('utf-8', 'ignore')
                t = re.sub(r'<[^>]+>', ' ', xml)
                if t:
                    texts.append(t)
                if sum(len(x) for x in texts) > max_chars:
                    break
    except Exception:
        return ''
    return ' '.join(texts)[:max_chars]


def score_text(text):
    scores = {k:0 for k in patterns}
    for subj, pats in patterns.items():
        for p in pats:
            matches = p.findall(text)
            if matches:
                # weight longer/phrase matches slightly more
                scores[subj] += len(matches)
    return scores


def classify(path):
    ext = os.path.splitext(path)[1].lower()
    if ext == '.pdf':
        text = extract_text_pdf(path)
    elif ext == '.docx':
        text = extract_text_docx(path)
    elif ext == '.pptx':
        text = extract_text_pptx(path)
    else:
        text = ''
    if not text:
        text = os.path.basename(path)
    scores = score_text(text)
    # choose best score
    best_subj = max(scores, key=lambda k: scores[k])
    if all(v==0 for v in scores.values()):
        best_subj = 'music_history'
    return best_subj, scores

files = [os.path.join(root,f) for f in os.listdir(root)]
files = [f for f in files if os.path.isfile(f)]

results = []
for f in sorted(files):
    subj, scores = classify(f)
    results.append((f, subj, scores))

# show summary counts and some low-confidence cases
counts = defaultdict(int)
for _, subj, _ in results:
    counts[subj]+=1

print('Counts:')
for k in ['LLM','trapped_ion_and_qc','black_hole','DNA','music_history']:
    print(k, counts[k])

# show items with low max score
print('\nLow-score items (max score <=1):')
for f, subj, scores in results:
    m = max(scores.values())
    if m <= 1:
        print(os.path.basename(f), '->', subj, scores)
